post.script:
(() => {
  if (window.renderWinchDesignTriangle) return;

  const NS = "http://www.w3.org/2000/svg";

  function clamp01(v) {
    v = Number(v);
    if (!Number.isFinite(v)) return 0.5;
    return Math.max(0, Math.min(1, v));
  }

  function renderWinchDesignTriangle(el, options) {
    if (el.getAttribute("data-rendered") === "true") return;
    el.setAttribute("data-rendered", "true");

    const scores = {
      price: clamp01(options.price),
      performance: clamp01(options.performance),
      complexity: clamp01(options.complexity)
    };

    const svg = document.createElementNS(NS, "svg");
    svg.setAttribute("viewBox", "0 0 600 480");
    svg.setAttribute("role", "img");
    svg.setAttribute(
      "aria-label",
      "Winch design triangle. Larger filled area means a better design across low price, high performance, and low complexity."
    );
    svg.style.width = "100%";
    svg.style.height = "auto";
    svg.style.display = "block";
    svg.style.borderRadius = "4px";

    el.textContent = "";
    el.appendChild(svg);

    function add(tag, attrs) {
      const node = document.createElementNS(NS, tag);
      Object.keys(attrs || {}).forEach(key => node.setAttribute(key, attrs[key]));
      svg.appendChild(node);
      return node;
    }

    function label(x, y, value, attrs) {
      const t = add("text", Object.assign({
        x,
        y,
        "font-family": "system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif",
        "font-size": "18",
        "font-weight": "500"
      }, attrs || {}));
      t.textContent = value;
      return t;
    }

    const A = { x: 300, y: 53.33,  key: "price",       color: "#2f7d32" };
    const B = { x: 96.67, y: 396.67, key: "performance", color: "#1e67b1" };
    const C = { x: 503.33, y: 396.67, key: "complexity",  color: "#d88400" };

    const O = {
      x: (A.x + B.x + C.x) / 3,
      y: (A.y + B.y + C.y) / 3
    };

    function pointOnAxis(vertex, value) {
      return {
        x: O.x + (vertex.x - O.x) * value,
        y: O.y + (vertex.y - O.y) * value
      };
    }

    function towardCenter(point, amount) {
      return {
        x: O.x + (point.x - O.x) * amount,
        y: O.y + (point.y - O.y) * amount
      };
    }

    function points(points) {
      return points.map(p => p.x.toFixed(1) + "," + p.y.toFixed(1)).join(" ");
    }

    add("rect", {
      x: 0,
      y: 0,
      width: 600,
      height: 480,
      fill: "#fbfaf7"
    });

    [0.25, 0.5, 0.75].forEach(level => {
      add("polygon", {
        points: points([
          pointOnAxis(A, level),
          pointOnAxis(B, level),
          pointOnAxis(C, level)
        ]),
        fill: "none",
        stroke: "#9aa0a6",
        "stroke-width": "1.4",
        "stroke-dasharray": "5 8",
        opacity: "0.45"
      });
    });

    [A, B, C].forEach(v => {
      add("line", {
        x1: O.x,
        y1: O.y,
        x2: v.x,
        y2: v.y,
        stroke: "#9aa0a6",
        "stroke-width": "1.2",
        "stroke-dasharray": "5 8",
        opacity: "0.55"
      });
    });

    add("line", { x1: B.x, y1: B.y, x2: A.x, y2: A.y, stroke: B.color, "stroke-width": 5, "stroke-linecap": "round" });
    add("line", { x1: A.x, y1: A.y, x2: C.x, y2: C.y, stroke: C.color, "stroke-width": 5, "stroke-linecap": "round" });
    add("line", { x1: B.x, y1: B.y, x2: C.x, y2: C.y, stroke: "#557b62", "stroke-width": 5, "stroke-linecap": "round" });

    const pA = pointOnAxis(A, scores.price);
    const pB = pointOnAxis(B, scores.performance);
    const pC = pointOnAxis(C, scores.complexity);

    add("polygon", {
      points: points([pA, pB, pC]),
      fill: "#8fbf9f",
      "fill-opacity": "0.34",
      stroke: "#174f59",
      "stroke-width": "5",
      "stroke-linejoin": "round"
    });

    add("polygon", {
      points: points([O, pA, pB]),
      fill: A.color,
      "fill-opacity": "0.12",
      stroke: "none"
    });

    add("polygon", {
      points: points([O, pB, pC]),
      fill: B.color,
      "fill-opacity": "0.10",
      stroke: "none"
    });

    add("polygon", {
      points: points([O, pC, pA]),
      fill: C.color,
      "fill-opacity": "0.12",
      stroke: "none"
    });

    [0.33, 0.66].forEach(level => {
      add("polygon", {
        points: points([
          towardCenter(pA, level),
          towardCenter(pB, level),
          towardCenter(pC, level)
        ]),
        fill: "none",
        stroke: "#174f59",
        "stroke-width": "1.5",
        "stroke-dasharray": "4 6",
        opacity: "0.5"
      });
    });

    [A, B, C].forEach(v => {
      add("circle", {
        cx: v.x,
        cy: v.y,
        r: 12,
        fill: v.color,
        stroke: "#fbfaf7",
        "stroke-width": 4
      });
    });

    [
      { p: pA, color: A.color },
      { p: pB, color: B.color },
      { p: pC, color: C.color }
    ].forEach(({ p, color }) => {
      add("circle", {
        cx: p.x,
        cy: p.y,
        r: 8,
        fill: color,
        stroke: "#fbfaf7",
        "stroke-width": 4
      });
    });

    label(A.x, A.y - 36, "Low Price", {
      fill: A.color,
      "text-anchor": "middle"
    });

    label(B.x - 8, B.y + 54, "High Performance", {
      fill: B.color,
      "text-anchor": "start"
    });

    label(C.x + 8, C.y + 54, "Low Complexity", {
      fill: C.color,
      "text-anchor": "end"
    });
  }

  window.renderWinchDesignTriangle = renderWinchDesignTriangle;

  function renderAll() {
    document.querySelectorAll(".winch-design-triangle").forEach(el => {
      renderWinchDesignTriangle(el, {
        price: el.getAttribute("data-price"),
        performance: el.getAttribute("data-performance"),
        complexity: el.getAttribute("data-complexity")
      });
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", renderAll);
  } else {
    renderAll();
  }
})();
